from __future__ import annotations

import json
import re
from typing import Any

_JSON_BLOCK_RE = re.compile(r"```json\s*(\{.*?\})\s*```", re.DOTALL | re.IGNORECASE)
_TRAJECTORY_KEYS = ("trajectory_1", "trajectory_2")
_STEP_REQUIRED_KEYS = {"step_id", "reason", "helps"}
_TRUE_LITERALS = {"true", "1", "yes", "y", "correct", 'positive'}
_FALSE_LITERALS = {"false", "0", "no", "n", "incorrect", 'negative'}


def remove_think_tags(input_string):
    # 使用正则表达式去除 <think> 和 </think> 标签之间的内容
    result = re.sub(r'<think>.*?</think>', '', input_string, flags=re.DOTALL)
    result = result.strip()
    return result



class RewardFormatError(Exception):
    """Raised when the model output or metadata cannot be parsed."""


def compute_score(
    solution_str: str, ground_truth: Any, *, extra_info: dict | None = None, **_: Any
) -> dict[str, Any]:
    """
    Return a dict with score and diagnostics so both train/validate dumps include failure reasons.
    Keys:
      - score: float in [-1, 1]
      - pc_err_stage: '' or stage tag (extract_json | load_trajectories | validate_steps | final_compare_or_truth)
      - pc_err: '' or brief error message (<=200 chars)
      - pc_json_found: bool indicating whether a ```json block was present
      - pc_step_len_t1 / pc_step_len_t2: integers if available
    """

    # normalize think tags if present
    if not solution_str.startswith("<think>") and '<think>' in solution_str and '</think>' in solution_str:
        solution_str = '<think>\n' + solution_str
    solution_str = remove_think_tags(solution_str)

    diag: dict[str, Any] = {
        "pc_err_stage": "",
        "pc_err": "",
        "pc_json_found": bool(_JSON_BLOCK_RE.search(solution_str) is not None),
        # Default to 0 so downstream metric aggregation never sees None entries.
        "pc_step_len_t1": 0,
        "pc_step_len_t2": 0,
    }

    try:
        parsed = _extract_response_json(solution_str)
    except RewardFormatError as e:
        diag["pc_err_stage"] = "extract_json"
        diag["pc_err"] = str(e)[:200]
        return {"score": -1.0, **diag}

    try:
        trajectories = _load_trajectories(extra_info)
        diag["pc_step_len_t1"] = len(trajectories.get("trajectory_1", {}))
        diag["pc_step_len_t2"] = len(trajectories.get("trajectory_2", {}))
    except RewardFormatError as e:
        diag["pc_err_stage"] = "load_trajectories"
        diag["pc_err"] = str(e)[:200]
        return {"score": -1.0, **diag}

    try:
        _validate_step_evaluations(parsed, trajectories)
    except RewardFormatError as e:
        diag["pc_err_stage"] = "validate_steps"
        diag["pc_err"] = str(e)[:200]
        return {"score": -1.0, **diag}

    try:
        score = _score_final(parsed, ground_truth)
    except RewardFormatError as e:
        diag["pc_err_stage"] = "final_compare_or_truth"
        diag["pc_err"] = str(e)[:200]
        return {"score": -1.0, **diag}

    return {"score": float(score), **diag}


def _extract_response_json(solution_str: str) -> dict[str, Any]:
    match = _JSON_BLOCK_RE.search(solution_str)
    if not match:
        raise RewardFormatError("missing ```json``` block")
    try:
        obj = json.loads(match.group(1))
    except json.JSONDecodeError as exc:
        raise RewardFormatError("invalid json block") from exc
    if not isinstance(obj, dict):
        raise RewardFormatError("json block must be an object")
    if "step_evaluations" not in obj or "final_comparison" not in obj:
        raise RewardFormatError("required keys missing from response")
    return obj


def _load_trajectories(extra_info: dict | None) -> dict[str, dict[str, Any]]:
    if not isinstance(extra_info, dict):
        raise RewardFormatError("extra_info must be provided")
    trajectories: dict[str, dict[str, Any]] = {}
    for key in _TRAJECTORY_KEYS:
        if key not in extra_info:
            raise RewardFormatError(f"missing '{key}' in extra_info")
        raw = extra_info[key]
        try:
            if isinstance(raw, str):
                traj_dict = json.loads(raw)
            elif isinstance(raw, dict):
                traj_dict = raw
            else:
                raise TypeError
        except (json.JSONDecodeError, TypeError) as exc:
            raise RewardFormatError(f"invalid trajectory data for {key}") from exc
        if not isinstance(traj_dict, list):
            raise RewardFormatError(f"trajectory '{key}' must decode to a list")
        trajectories[key] = traj_dict
    return trajectories


def _validate_step_evaluations(parsed: dict[str, Any], trajectories: dict[str, dict[str, Any]]) -> None:
    step_evals = parsed.get("step_evaluations")
    if not isinstance(step_evals, dict):
        raise RewardFormatError("step_evaluations must be a dict")

    for key in _TRAJECTORY_KEYS:
        steps = step_evals.get(key)
        if not isinstance(steps, list):
            raise RewardFormatError(f"step_evaluations['{key}'] must be a list")
        if len(steps) != len(trajectories[key]):
            raise RewardFormatError(f"step count mismatch for {key}")

        seen_step_ids: set[int] = set()
        for entry in steps:
            if not isinstance(entry, dict):
                raise RewardFormatError("step evaluation entry must be a dict")
            if not _STEP_REQUIRED_KEYS.issubset(entry.keys()):
                raise RewardFormatError("step evaluation missing required fields")

            step_id = _coerce_step_id(entry["step_id"])
            if step_id < 0 or step_id >= len(trajectories[key]):
                raise RewardFormatError("step_id out of range")
            if step_id in seen_step_ids:
                raise RewardFormatError("duplicate step_id in trajectory evaluation")
            seen_step_ids.add(step_id)

            reason = entry["reason"]
            if not isinstance(reason, str) or not reason.strip():
                raise RewardFormatError("reason must be a non-empty string")

            _ = _coerce_bool(entry["helps"])  # Validate boolean-like values


def _score_final(parsed: dict[str, Any], ground_truth: Any) -> float:
    final_cmp = parsed.get("final_comparison")
    if not isinstance(final_cmp, dict):
        raise RewardFormatError("final_comparison must be a dict")
    if "reason" not in final_cmp or not isinstance(final_cmp["reason"], str):
        raise RewardFormatError("final_comparison must include textual reason")

    try:
        pred_t1 = _coerce_bool(final_cmp["trajectory_1_final_correct"])
        pred_t2 = _coerce_bool(final_cmp["trajectory_2_final_correct"])
    except KeyError as exc:
        raise RewardFormatError("final comparison missing correctness flags") from exc

    truth = _load_ground_truth(ground_truth)

    reward = 0.0
    if pred_t1 == truth["trajectory_1"] and pred_t2 == truth["trajectory_2"]:
        reward += 1.0
    # if pred_t2 == truth["trajectory_2"]:
    #     reward += 0.5
    return reward


def _load_ground_truth(ground_truth: Any) -> dict[str, bool]:
    if isinstance(ground_truth, str):
        try:
            data = json.loads(ground_truth)
        except json.JSONDecodeError as exc:
            raise RewardFormatError("ground_truth must be json-decodable") from exc
    elif isinstance(ground_truth, dict):
        data = ground_truth
    else:
        raise RewardFormatError("ground_truth must be dict or json string")

    truth: dict[str, bool] = {}
    for key in _TRAJECTORY_KEYS:
        if key not in data:
            raise RewardFormatError(f"ground_truth missing '{key}'")
        truth[key] = _coerce_bool(data[key])
    return truth


def _coerce_bool(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    if isinstance(value, str):
        lowered = value.strip().lower()
        if lowered in _TRUE_LITERALS:
            return True
        if lowered in _FALSE_LITERALS:
            return False
    raise RewardFormatError("value is not interpretable as boolean")


def _coerce_step_id(value: Any) -> int:
    if isinstance(value, int):
        return value
    if isinstance(value, str) and value.isdigit():
        return int(value)
    raise RewardFormatError("step_id must be integer-like")

